const fs = require('fs');
const path = require('path');

// ← Change this if your path is different
// const DIR = '/data/grascco_pii_2_json';
const DIR = '/home/node/.n8n-files/grascco_pii_2_json';


let files = fs.readdirSync(DIR).filter(f => f.endsWith('.json'));
if (files.length === 0) throw new Error('No .json files found at: ' + DIR);
files = files.slice(0, 1);
const results = [];

for (const fileName of files) {
  let cas;
  try {
    let raw = fs.readFileSync(path.join(DIR, fileName), 'utf-8');
    if (raw.charCodeAt(0) === 0xFEFF) {
        raw = raw.slice(1);
    }
    cas = JSON.parse(raw);
  } catch (e) {
    continue;
  }

  const features = cas['%FEATURE_STRUCTURES'];
  if (!features) continue;

  const sofa = features.find(f => f['%TYPE'] === 'uima.cas.Sofa');
  const text = sofa?.sofaString || '';
  if (!text) continue;

  const meta = features.find(f =>
    f['%TYPE'] === 'de.tudarmstadt.ukp.dkpro.core.api.metadata.type.DocumentMetaData'
  );
  const doc_id = meta?.documentTitle || fileName;

  const phiAnnotations = features.filter(f => f['%TYPE'] === 'webanno.custom.PHI');
  const ground_truth = {
    doc_id,
    pii: phiAnnotations
      .map(a => ({ type: a.kind, value: text.substring(a.begin, a.end) }))
      .filter(a => a.value.trim() !== '')
  };

  results.push({ json: { text, language: 'de', doc_id, ground_truth } });
}

return results;

// NODO A VITAMINADO: Detección Mejorada mediante Regex (Optimizado para Alemán)
const data = $input.first().json;
const text = data.text || "";
const found = [];
const push = (type, value) => {
  value = (value || "").trim().replace(/\s{2,}[\s\S]*$/, "");
  if (value && !found.some(e => e.type === type && e.value === value)) {
    found.push({ type, value });
  }
};

// 1. FECHAS
const dateRegex = /\b\d{1,2}\.\d{1,2}\.(?:\d{4})?\b/g;
(text.match(dateRegex) || []).forEach(v => push("DATE", v));

const yearRegex = /\b(19|20)\d{2}\b/g;
(text.match(yearRegex) || []).forEach(v => {
  if (!text.match(new RegExp('\\d{1,2}\\.\\d{1,2}\\.' + v))) {
    push("DATE", v);
  }
});

// 2. EMAILS Y TELÉFONOS
(text.match(/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g) || []).forEach(v => push("EMAIL", v));

// --- FIX: descartar fechas/timestamps que el regex confunde con teléfonos ---
(text.match(/(?<![A-Za-z0-9+])\+?\d[\d()\/ .-]{7,}\d/g) || []).forEach(v => {
  const val = v.trim();
  // Si empieza como una fecha dd.dd.dddd, NO es un teléfono (ej. "24.12.2027 17")
  if (/^\d{1,2}\.\d{1,2}\.\d{2,4}/.test(val)) return;
  const digits = val.replace(/\D/g, "");
  if (digits.length >= 9 && digits.length <= 15) push("PHONE", val);
});

// 3. EDAD
const ageRegex = /\b(\d{1,3})(?=-jährigen|-jährige|-jähriger| Jahre alt)\b/gi;
let ageMatch; while ((ageMatch = ageRegex.exec(text)) !== null) push("AGE", ageMatch[1]);

// 4. PROFESIONES
const profRegex = /\b(?:ist|arbeitet als)\s+([A-Z][a-zßäöü]+in|[A-Z][a-zßäöü]+)\b/g;
let profMatch; while ((profMatch = profRegex.exec(text)) !== null) {
  const forbidden = ["Patientin", "Frau", "Herr"];
  if (!forbidden.includes(profMatch[1])) push("PROFESSION", profMatch[1]);
}

// 5. NOMBRES
const forbidden = ["Patientin", "Patient", "Frau", "Herr", "Kollegin", "Kollege"]; // FIX: añadidos Kollegin/Kollege
const genericNameRegex = /(?:Patient(?:in)?|Frau|Herr)\s+([A-Z][a-zßäöü]*\.?\s*[A-Z][a-zßäöü]+|[A-Z][a-zßäöü]+)/g;
let nm; while ((nm = genericNameRegex.exec(text)) !== null) {
  const cand = nm[1].trim();
  if (!forbidden.includes(cand)) push("NAME", cand);   // FIX: filtro aplicado aquí
}

const doctorRegex = /([A-Z][a-zßäöü]+\s+[A-Z][a-zßäöü]+)\n(?:Stationsarzt|Arzt|Chefartz)/gi;
let dm; while ((dm = doctorRegex.exec(text)) !== null) push("NAME", dm[1].trim());

return [{ json: { ...data, entities: [...(data.entities || []), ...found] } }];

// NODO MERGE (Option 1): re-adjunta el documento original + une regex + LLM
// El item de entrada es la salida del LLM (solo trae el output del modelo).
const llmItem = $input.first().json;

// --- Recuperar el documento original (text + ground_truth + doc_id + entities de regex) ---
// >>> CAMBIA 'Regex' por el nombre EXACTO de tu nodo de regex en el canvas <
// const orig = $('Regex').first().json;
const orig = $('A - Detect (regex)').first().json;

const regexEntities = orig.entities || [];

// --- Parsear salida del LLM (puede venir como string JSON o ya parseada) ---
let llmRaw = llmItem.output ?? llmItem.llm ?? llmItem.new_entities ?? llmItem.entities ?? [];
if (typeof llmRaw === "string") {
  try { llmRaw = JSON.parse(llmRaw.replace(/```json|```/g, "").trim()); }
  catch { llmRaw = []; }
}
const llmEntities = Array.isArray(llmRaw)
  ? llmRaw
  : (llmRaw.entities || llmRaw.new_entities || []);

// --- Separador de títulos: "Prof. Dr. Norbert Breuer" -> título + nombre ---
const TITLE_RE = /(Priv\.-Doz\.\s*Dr\.\s*med\.|Priv\.-Doz\.|Prof\.\s*Dr\.|Prof\.|Drs\.|Dr\.\s*med\.|Dr\.med\.|Dr\.)/g;

function splitTitleName(type, value) {
  const out = [];
  const v = (value || "").trim();
  if (!v) return out;

  const isName = /NAME/i.test(type) || type === "NAME";
  if (isName) {
    const titles = [];
    const name = v.replace(TITLE_RE, (m) => { titles.push(m.replace(/\s+/g, " ").trim()); return " "; })
                  .replace(/\s+/g, " ").trim();
    for (const t of titles) out.push({ type: "NAME_TITLE", value: t });
    if (name) out.push({ type, value: name });
    if (!name && titles.length === 0) out.push({ type, value: v });
    return out;
  }
  out.push({ type, value: v });
  return out;
}

// --- Limpieza de valores (ej. "* 4.4.1993" -> "4.4.1993") ---
const cleanValue = (v) => (v || "").trim().replace(/^[*\s•\-]+/, "").replace(/\s+/g, " ").trim();

// --- Construir lista combinada (regex + LLM), aplicando split de títulos ---
const combined = [];
for (const e of [...regexEntities, ...llmEntities]) {
  if (!e || !e.value) continue;
  const cleaned = cleanValue(e.value);
  for (const split of splitTitleName(e.type || "NAME", cleaned)) {
    combined.push(split);
  }
}

// --- Guard anti-alucinación: descartar fechas cuyos dígitos no estén en el texto ---
const sourceDigits = (orig.text || "").replace(/\D/g, "");
const filtered = combined.filter(e => {
  if (/DATE/i.test(e.type)) {
    const d = (e.value || "").replace(/\D/g, "");
    if (d.length >= 4 && !sourceDigits.includes(d)) return false;
  }
  return true;
});

// --- Deduplicar por (familia de tipo, valor normalizado) ---
const typeFamily = (t) => {
  t = (t || "").toUpperCase();
  if (t.includes("NAME") || t.includes("TITLE")) return "NAME";
  if (t.includes("DATE") || t.includes("BIRTH")) return "DATE";
  if (t.includes("EMAIL")) return "EMAIL";
  if (t.includes("PHONE") || t.includes("CONTACT")) return "PHONE";
  return t;
};
const norm = (s) => (s || "").trim().toLowerCase().replace(/\s+/g, " ");

const seen = new Set();
const merged = [];
for (const e of filtered) {
  const key = typeFamily(e.type) + "::" + norm(e.value);
  if (seen.has(key)) continue;
  seen.add(key);
  merged.push({ type: e.type, value: e.value });
}

// --- Devolver el documento original COMPLETO con las entidades fusionadas ---
return [{ json: {
  ...orig,            // text, ground_truth, doc_id, language, etc.
  entities: merged    // sobrescribe con la lista fusionada
}}];

const data = $input.first().json;
const text = data.text || "";
const lang = (data.language || "de").slice(0, 2);
const entities = data.entities || [];
const POOLS = {
  de: { first:["Erik","Lena","Jonas","Mara","Felix","Nina"], last:["Bauer","Schwarz","Hoffmann","Kraus","Vogt","Lang"],
        street:["Gartenweg","Lindenstrasse","Birkenallee","Ulmenweg"], city:["Lindau","Kempten","Memmingen","Bergstadt"] },
  fr: { first:["Lucas","Emma","Hugo","Lea","Nathan","Chloe"], last:["Martin","Petit","Roche","Garnier","Blanc","Noel"],
        street:["rue des Lilas","avenue Verte","rue Haute","allee des Pins"], city:["Valbonne","Beaulieu","Montfleur","Rivedoux"] },
  es: { first:["Marcos","Lucia","Ivan","Nerea","Diego","Carla"], last:["Soler","Vidal","Bravo","Ortega","Ferrer","Pardo"],
        street:["calle del Olmo","avenida Azul","calle Mayor","plaza Verde"], city:["Vallclara","San Roque","Riofrio","Costaverde"] }
};
const pool = POOLS[lang] || POOLS.de;
const rng = n => Math.floor(Math.random() * n);
const pick = a => a[rng(a.length)];
const mapping = {};
const shiftDate = v => {
  let d, fmt;
  let m = v.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (m) { d = new Date(+m[3], +m[2] - 1, +m[1]); fmt = "dmy."; }
  if (!d) {
  const partial = v.match(/^(\d{1,2})\.(\d{1,2})\.$/);
    if (partial) {
      const day = ((parseInt(partial[1]) - 1 + rng(25) + 1) % 28) + 1;
      const mon = ((parseInt(partial[2]) - 1 + rng(10) + 1) % 12) + 1;
      return `${String(day).padStart(2,'0')}.${String(mon).padStart(2,'0')}.`;
    }
  }
  if (!d) { m = v.match(/^(\d{4})-(\d{2})-(\d{2})$/); if (m) { d = new Date(+m[1], +m[2] - 1, +m[3]); fmt = "ymd-"; } }
  if (!d) { m = v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/); if (m) { d = new Date(+m[3], +m[2] - 1, +m[1]); fmt = "dmy/"; } }
  if (!d || isNaN(d)) return v;
  const offset = (rng(90) + 1) * (rng(2) === 0 ? 1 : -1);
  d.setDate(d.getDate() + offset);
  const dd = String(d.getDate()).padStart(2, "0");
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const yyyy = d.getFullYear();
  if (fmt === "dmy.") return `${dd}.${mm}.${yyyy}`;
  if (fmt === "ymd-") return `${yyyy}-${mm}-${dd}`;
  if (fmt === "dmy/") return `${dd}/${mm}/${yyyy}`;
  return v;
};

const fakeFor = (type, value) => {
  if (mapping[value]) return mapping[value];
  let fake;
  if (type === "NAME") fake = pick(pool.first) + " " + pick(pool.last);
  else if (type === "ADDRESS") fake = pick(pool.street) + " " + (1 + rng(120)) + ", " + (10000 + rng(89999)) + " " + pick(pool.city);
  else if (type === "DATE") fake = shiftDate(value);
  else if (type === "EMAIL") fake = pick(pool.first).toLowerCase() + (10 + rng(89)) + "@example.org";
  else fake = value.replace(/\d/g, () => String(rng(10)));
  mapping[value] = fake; return fake;
};
entities.forEach(e => fakeFor(e.type, e.value));
let out = text;
Object.keys(mapping).sort((a, b) => b.length - a.length).forEach(real => { out = out.split(real).join(mapping[real]); });
return [{ json: { original_text: text, pseudonymized_text: out, mapping, entities, language: lang } }];

const resp = $input.first().json;
const mapping = $('B - Pseudonymize').first().json.mapping || {};
const analysis = resp.output ?? resp.text ?? (resp.message && resp.message.content) ?? "";
let out = analysis;
const inv = {}; Object.entries(mapping).forEach(([r, f]) => inv[f] = r);
Object.keys(inv).sort((a, b) => b.length - a.length).forEach(f => { out = out.split(f).join(inv[f]); });
return [{ json: { analysis_text: analysis, restored_text: out, mapping } }];

const gt = $('Load Input').first().json.ground_truth || {};
const gtList = (gt.pii || []).map(e => e.value);
const entities = ($('B - Pseudonymize').first().json.entities || []).map(e => e.value);
const mapping = $('B - Pseudonymize').first().json.mapping || {};
const restored = $input.first().json.restored_text || "";
const uniq = a => [...new Set(a)];
const has = (set, x) => set.includes(x);
const gtS = uniq(gtList), det = uniq(entities);
const dTP = det.filter(v => has(gtS, v)).length;
const dFP = det.filter(v => !has(gtS, v)).length;
const dFN = gtS.filter(v => !has(det, v)).length;
let rTP = 0, rFN = 0, rFP = 0;
Object.entries(mapping).forEach(([real, fake]) => {
  if (restored.includes(real)) rTP++; else rFN++;
  if (restored.includes(fake)) rFP++;
});
const ratio = (a, b) => (a + b === 0 ? null : +(a / (a + b)).toFixed(3));
const f1 = (p, r) => (p == null || r == null || p + r === 0 ? null : +(2 * p * r / (p + r)).toFixed(3));
const dP = ratio(dTP, dFP), dR = ratio(dTP, dFN), rP = ratio(rTP, rFP), rR = ratio(rTP, rFN);
return [{ json: {
  doc_id: gt.doc_id || null,
  detection: { tp: dTP, fp: dFP, fn: dFN, precision: dP, recall: dR, f1: f1(dP, dR), missed: gtS.filter(v => !has(det, v)) },
  restoration: { tp: rTP, fp: rFP, fn: rFN, precision: rP, recall: rR, f1: f1(rP, rR) },
  restored_text: restored
} }];

let text = $json.restored_text;

// Bold
text = text.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

// Convert bullet points
text = text.replace(/^- (.*)$/gm, "<li>$1</li>");

// Wrap consecutive <li> items in <ul>
text = text.replace(/(<li>.*?<\/li>\n?)+/gs, match => `<ul>${match}</ul>`);

// Line breaks
text = text.replace(/\n/g, "<br>");

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body{
    font-family: Arial, sans-serif;
    margin:40px;
    line-height:1.5;
}
ul{
    margin-left:20px;
}
</style>
</head>
<body>
${text}
</body>
</html>
`;

return [{
    json: {
        html
    },
  binary: {
    index_html: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
}];

// NODO DE EVALUACIÓN (post-merge): Precision / Recall / F1
const items = $input.all();

const typeFamily = (t) => {
  t = (t || "").toUpperCase();
  if (t.includes("NAME") || t.includes("TITLE")) return "NAME";
  if (t.includes("DATE") || t.includes("BIRTH")) return "DATE";
  if (t.includes("EMAIL")) return "EMAIL";
  if (t.includes("PHONE")) return "PHONE";
  if (t.includes("AGE")) return "AGE";
  if (t.includes("PROFESSION")) return "PROFESSION";
  return t;
};
const norm = (s) => (s || "").trim().toLowerCase().replace(/\s+/g, " ");
const valueMatch = (a, b) => {
  a = norm(a); b = norm(b);
  if (!a || !b) return false;
  if (a === b) return true;
  if (a.length >= 3 && b.length >= 3 && (a.includes(b) || b.includes(a))) return true;
  return false;
};

let totalTP = 0, totalFP = 0, totalFN = 0;
const perDoc = [];

for (const item of items) {
  const data = item.json;
  const detected = data.entities || [];

  // --- OPTION A: dedupe ground truth by family + normalized value ---
  const seenTruth = new Set();
  const truth = ((data.ground_truth && data.ground_truth.pii) || []).filter(t => {
    const k = typeFamily(t.type) + "::" + norm(t.value);
    if (seenTruth.has(k)) return false;
    seenTruth.add(k);
    return true;
  });
  // -----------------------------------------------------------------

  const truthUsed = new Array(truth.length).fill(false);
  let tp = 0;
  const tpList = [], fpList = [];

  for (const det of detected) {
    const dFam = typeFamily(det.type);
    let matchedIdx = -1;
    for (let i = 0; i < truth.length; i++) {
      if (truthUsed[i]) continue;
      if (typeFamily(truth[i].type) === dFam && valueMatch(det.value, truth[i].value)) {
        matchedIdx = i; break;
      }
    }
    if (matchedIdx >= 0) {
      truthUsed[matchedIdx] = true; tp++;
      tpList.push({ detected: det.value, matched: truth[matchedIdx].value, type: dFam });
    } else {
      fpList.push({ value: det.value, type: det.type });
    }
  }

  const fnList = [];
  for (let i = 0; i < truth.length; i++)
    if (!truthUsed[i]) fnList.push({ value: truth[i].value, type: truth[i].type });

  const fp = fpList.length, fn = fnList.length;
  const precision = (tp + fp) === 0 ? 0 : tp / (tp + fp);
  const recall = (tp + fn) === 0 ? 0 : tp / (tp + fn);
  const f1 = (precision + recall) === 0 ? 0 : (2 * precision * recall) / (precision + recall);

  totalTP += tp; totalFP += fp; totalFN += fn;
  perDoc.push({
    doc_id: data.doc_id || "unknown",
    stage: "after_merge",
    tp, fp, fn,
    precision: +precision.toFixed(4),
    recall: +recall.toFixed(4),
    f1: +f1.toFixed(4),
    true_positives: tpList,
    false_positives: fpList,
    false_negatives: fnList
  });
}

const mP = (totalTP + totalFP) === 0 ? 0 : totalTP / (totalTP + totalFP);
const mR = (totalTP + totalFN) === 0 ? 0 : totalTP / (totalTP + totalFN);
const mF1 = (mP + mR) === 0 ? 0 : (2 * mP * mR) / (mP + mR);

return [{ json: {
  summary: {
    stage: "after_merge",
    documents: perDoc.length,
    total_tp: totalTP, total_fp: totalFP, total_fn: totalFN,
    precision: +mP.toFixed(4), recall: +mR.toFixed(4), f1: +mF1.toFixed(4)
  },
  per_document: perDoc
}}];

// NODO DE EVALUACIÓN: Precision / Recall / F1
// Compara `entities` (detectado) contra `ground_truth.pii` (verdad)
const items = $input.all();
const results = [];

const typeFamily = (t) => {
  t = (t || "").toUpperCase();
  if (t.includes("NAME") || t.includes("TITLE")) return "NAME";
  if (t.includes("DATE") || t.includes("BIRTH")) return "DATE";
  if (t.includes("EMAIL")) return "EMAIL";
  if (t.includes("PHONE")) return "PHONE";
  if (t.includes("AGE")) return "AGE";
  if (t.includes("PROFESSION")) return "PROFESSION";
  return t;
};
const norm = (s) => (s || "").trim().toLowerCase().replace(/\s+/g, " ");
const valueMatch = (a, b) => {
  a = norm(a); b = norm(b);
  if (!a || !b) return false;
  if (a === b) return true;
  if (a.length >= 3 && b.length >= 3 && (a.includes(b) || b.includes(a))) return true;
  return false;
};

let totalTP = 0, totalFP = 0, totalFN = 0;
const perDoc = [];

for (const item of items) {
  const data = item.json;
  const detected = data.entities || [];

  // --- OPTION A: dedupe ground truth by family + normalized value ---
  const seenTruth = new Set();
  const truth = ((data.ground_truth && data.ground_truth.pii) || []).filter(t => {
    const k = typeFamily(t.type) + "::" + norm(t.value);
    if (seenTruth.has(k)) return false;
    seenTruth.add(k);
    return true;
  });
  // -----------------------------------------------------------------

  const truthUsed = new Array(truth.length).fill(false);
  let tp = 0;
  const tpList = [], fpList = [];

  for (const det of detected) {
    const dFam = typeFamily(det.type);
    let matchedIdx = -1;
    for (let i = 0; i < truth.length; i++) {
      if (truthUsed[i]) continue;
      if (typeFamily(truth[i].type) === dFam && valueMatch(det.value, truth[i].value)) {
        matchedIdx = i;
        break;
      }
    }
    if (matchedIdx >= 0) {
      truthUsed[matchedIdx] = true;
      tp++;
      tpList.push({ detected: det.value, matched: truth[matchedIdx].value, type: dFam });
    } else {
      fpList.push({ value: det.value, type: det.type });
    }
  }

  const fnList = [];
  for (let i = 0; i < truth.length; i++) {
    if (!truthUsed[i]) fnList.push({ value: truth[i].value, type: truth[i].type });
  }

  const fp = fpList.length;
  const fn = fnList.length;
  const precision = (tp + fp) === 0 ? 0 : tp / (tp + fp);
  const recall = (tp + fn) === 0 ? 0 : tp / (tp + fn);
  const f1 = (precision + recall) === 0 ? 0 : (2 * precision * recall) / (precision + recall);

  totalTP += tp; totalFP += fp; totalFN += fn;
  perDoc.push({
    doc_id: data.doc_id || "unknown",
    tp, fp, fn,
    precision: +precision.toFixed(4),
    recall: +recall.toFixed(4),
    f1: +f1.toFixed(4),
    true_positives: tpList,
    false_positives: fpList,
    false_negatives: fnList
  });
}

const microPrecision = (totalTP + totalFP) === 0 ? 0 : totalTP / (totalTP + totalFP);
const microRecall = (totalTP + totalFN) === 0 ? 0 : totalTP / (totalTP + totalFN);
const microF1 = (microPrecision + microRecall) === 0 ? 0 : (2 * microPrecision * microRecall) / (microPrecision + microRecall);

return [{
  json: {
    summary: {
      documents: perDoc.length,
      total_tp: totalTP,
      total_fp: totalFP,
      total_fn: totalFN,
      precision: +microPrecision.toFixed(4),
      recall: +microRecall.toFixed(4),
      f1: +microF1.toFixed(4)
    },
    per_document: perDoc
  }
}];
